    private static final Path OUT=Path.of("../.runtime/native-previews/updates-terra").toAbsolutePath().normalize();
    private static int assertions;
    private static void check(boolean ok,String reason){assertions++;if(!ok)throw new AssertionError(reason);}
    private static Field f(Class<?> c,String name)throws Exception{Field field=c.getDeclaredField(name);field.setAccessible(true);return field;}
    private static Object state(HubView v)throws Exception{return f(HubView.class,"updates").get(v);}
    private static Object get(Object o,String name)throws Exception{return f(o.getClass(),name).get(o);}
    private static void set(Object o,String name,Object value)throws Exception{f(o.getClass(),name).set(o,value);}
    private static Object call(Object o,String name,Class<?>[] types,Object...args)throws Exception{Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(o,args);}
    private static void navigate(HubView v,int page)throws Exception{call(v,"navigate",new Class<?>[]{int.class},page);}
    private static String id(int n){return String.format(Locale.ROOT,"00000000-0000-0000-0000-%012d",n+2);}
    private static JsonObject row(int n){JsonObject r=UpdatesSessionChecks.snapshot().getAsJsonObject("list").getAsJsonArray("rows").get(0).getAsJsonObject().deepCopy();r.addProperty("id",id(n));r.addProperty("title",n==1?"A longer update title that uses several readable English words":"更新记录 "+n);r.addProperty("pinned",n==0);return r;}
    private static JsonObject page(int page,int total,Set<Integer> removed){JsonObject out=new JsonObject();JsonArray rows=new JsonArray();List<Integer> all=new ArrayList<>();for(int i=0;i<total;i++)if(!removed.contains(i))all.add(i);for(int i=page*12;i<Math.min(all.size(),(page+1)*12);i++)rows.add(row(all.get(i)));out.add("rows",rows);out.addProperty("total",all.size());out.addProperty("page",page);out.addProperty("size",12);JsonObject counts=new JsonObject();counts.addProperty("all",all.size());counts.addProperty("published",all.size());out.add("counts",counts);out.addProperty("latestId",id(0));return out;}
    private static JsonObject snapshot(int total){JsonObject s=UpdatesSessionChecks.snapshot();s.add("list",page(0,total,Set.of()));return s;}
    private static JsonObject read(int n){JsonObject r=UpdatesSessionChecks.reading();r.add("entry",row(n));r.getAsJsonObject("entry").addProperty("body","### Reading the update\nEnglish words remain together when possible.\n第一段正文与阅读卡内容。\n- 第一项\n- 第二项\n");return r;}
    private static final class Fixture {
        final HubView view=new HubView();final List<JsonObject> requests=new ArrayList<>();final Object state;
        Fixture(int total)throws Exception{view.live((module,action,payload)->{JsonObject p=payload.deepCopy();p.addProperty("action",action);requests.add(p);});view.setPlayerName("SyntheticPlayer");view.setSettings("login",true);view.setViewportBounds(-90,-75,1440,1000);view.open(false);view.acceptLive("updates","snapshot",snapshot(total));navigate(view,3);view.acceptLive("updates","read",read(0));state=state(view);}
        JsonObject last(String action){for(int i=requests.size()-1;i>=0;i--)if(requests.get(i).get("action").getAsString().equals(action))return requests.get(i);throw new AssertionError("No "+action+" request");}
        void reply(String action,JsonObject dto){JsonObject copy=dto.deepCopy(),request=last(action).deepCopy();request.remove("action");copy.add("_hubRequest",request);view.acceptLive("updates",action,copy);}
    }
    private static BufferedImage frame(HubRenderer renderer,Fixture t,String name,float mx,float my)throws Exception{
        glDisable(GL_SCISSOR_TEST);glClearColor(.65f,.72f,.85f,1);glClear(GL_COLOR_BUFFER_BIT);long now=System.nanoTime();renderer.render(1440,1000,90,75,1,true,d->t.view.render(d,mx,my,now));ByteBuffer bytes=MemoryUtil.memAlloc(1440*1000*4);try{glReadPixels(0,0,1440,1000,GL_RGBA,GL_UNSIGNED_BYTE,bytes);BufferedImage image=new BufferedImage(1440,1000,BufferedImage.TYPE_INT_ARGB);for(int y=0;y<1000;y++)for(int x=0;x<1440;x++){int i=((999-y)*1440+x)*4;image.setRGB(x,y,0xff000000|Byte.toUnsignedInt(bytes.get(i))<<16|Byte.toUnsignedInt(bytes.get(i+1))<<8|Byte.toUnsignedInt(bytes.get(i+2)));}if(name!=null)ImageIO.write(image,"PNG",OUT.resolve(name+".png").toFile());return image;}finally{MemoryUtil.memFree(bytes);}
    }
    private static BufferedImage frame(HubRenderer renderer,Fixture t,String name)throws Exception{return frame(renderer,t,name,-100,-100);}
    private static float num(Object o,String name)throws Exception{return ((Number)get(o,name)).floatValue();}
    private static List<JsonObject> objects(Object o,String name)throws Exception{return (List<JsonObject>)get(o,name);}
    private static void click(HubView v,float x,float y){v.mouseClicked(x,y,0);v.mouseReleased(x,y,0);}
    private static int light(BufferedImage img,int x,int y){int c=img.getRGB(x,y);return (c>>16&255)+(c>>8&255)+(c&255);}
    private static Object hit(HubView v,String id)throws Exception{for(Object item:(List<?>)get(v,"hits"))if(call(item,"id",new Class<?>[0]).equals(id))return item;throw new AssertionError("Missing hit "+id);}
    private static float coordinate(Object h,String name)throws Exception{return ((Number)call(h,name,new Class<?>[0])).floatValue();}
    private static void clickHit(HubView v,String id)throws Exception{Object h=hit(v,id);click(v,coordinate(h,"x")+5,coordinate(h,"y")+5);}
    private static JsonObject comment(int n){JsonObject c=new JsonObject();c.addProperty("id","10000000-0000-0000-0000-"+String.format("%012d",n));c.addProperty("text","自己的留言 "+n+"\n保留完整内容和时间。");c.addProperty("createdAt",1793837000000L+n);c.addProperty("replyCount",0);c.add("replies",new JsonArray());return c;}
    private static JsonObject commentsRead(int page,int total){JsonObject r=read(0);JsonObject p=new JsonObject();JsonArray rows=new JsonArray();for(int i=page*12;i<Math.min(total,(page+1)*12);i++)rows.add(comment(i));p.add("rows",rows);p.addProperty("total",total);p.addProperty("page",page);p.addProperty("size",12);r.add("comments",p);return r;}
    private static JsonObject replyRead(int page){
        JsonObject read=commentsRead(0,1),comment=read.getAsJsonObject("comments").getAsJsonArray("rows").get(0).getAsJsonObject();JsonArray rows=new JsonArray();int end=Math.max(0,45-page*20),start=Math.max(0,end-20);
        for(int i=start;i<end;i++){JsonObject reply=new JsonObject();reply.addProperty("id","30000000-0000-0000-0000-"+String.format("%012d",i));reply.addProperty("text","管理员的历史回复 "+i+"，按真实时间先后阅读。");reply.addProperty("createdAt",1793838000000L+i);rows.add(reply);}
        comment.add("replies",rows);comment.addProperty("replyCount",45);comment.addProperty("repliesPage",page);return read;
    }
